181	fn cell_spsc_v2(pin: Option<(usize, usize)>, pool_size: u32, depth: u32, count: u64) -> f64 {
182	    use zc_ring_x1::spsc::v2::{Ring, region_size};
183	    let slot = CACHE_LINE_SIZE as u32;
184	    let mut region = LineBuf::new(region_size(slot, depth));
185	    let (mut tx, mut rx) = Ring::init(region.as_mut_bytes(), slot, depth)
186	        .expect("region sized by region_size and line-aligned") // OK: the region is the ring's own size and LineBuf is line-aligned
187	        .split();
