189	        pin,
190	        pool_size,
191	        count,
192	        move |desc| {
193	            let mut slot = tx
194	                .reserve_slot_with::<Desc>(policy::spin)
195	                .expect("spin never gives up"); // OK: policy::spin never gives up
196	            *slot = desc;
197	            slot.commit();
198	        },
199	        move || {
200	            let slot = rx
201	                .reserve_slot_with::<Desc>(policy::spin)
202	                .expect("spin never gives up"); // OK: policy::spin never gives up
203	            let desc = *slot;
204	            slot.release();
205	            desc
206	        },
207	    )
