210	/// The MPSC v1 ring cell at 1p/1c: descriptors cross a v1 ring
211	/// of `depth` line-sized slots.
212	fn cell_mpsc_v1(pin: Option<(usize, usize)>, pool_size: u32, depth: u32, count: u64) -> f64 {
213	    use zc_ring_x1::mpsc::v1::{MpscRing, mpsc_region_size};
214	    let slot = CACHE_LINE_SIZE as u32;
215	    let mut region = LineBuf::new(mpsc_region_size(slot, depth));
216	    let (tx, mut rx) = MpscRing::init(region.as_mut_bytes(), slot, depth)
217	        .expect("region sized by mpsc_region_size and line-aligned") // OK: the region is the ring's own size and LineBuf is line-aligned
218	        .split();
219	    run_ring_cell(
220	        pin,
221	        pool_size,
222	        count,
223	        move |desc| {
224	            tx.send_with::<Desc>(policy::spin, |m| *m = desc)
225	                .expect("spin never gives up"); // OK: policy::spin never gives up
226	        },
227	        move || {
228	            let slot = rx
229	                .reserve_slot_with::<Desc>(policy::spin)
230	                .expect("spin never gives up"); // OK: policy::spin never gives up
