238	/// The ring rows' loop over a pool of `pool_size` buffers: the
239	/// producer allocs, fills, converts the guard to a descriptor,
240	/// and hands it to `send`, and the consumer takes one from
241	/// `recv`, resolves it, asserts the sequence, and frees.
242	fn run_ring_cell(
243	    pin: Option<(usize, usize)>,
244	    pool_size: u32,
245	    count: u64,
246	    mut send: impl FnMut(Desc) + Send,
247	    mut recv: impl FnMut() -> Desc + Send,
248	) -> f64 {
249	    let mut pool_region = LineBuf::new(pool_region_size(pool_size));
250	    let mut pool = Pool::init(
251	        pool_region.as_mut_bytes(),
252	        CACHE_LINE_SIZE as u32,
253	        pool_size,
254	    )
255	    .expect("region sized for the pool and line-aligned"); // OK: the region is the pool's own size and LineBuf is line-aligned
256	    let mut registry = PoolRegistry::<1>::new();
257	    let pool_id = registry
258	        .register(pool.resolver())
259	        .expect("an empty registry has room"); // OK: capacity 1, nothing registered yet
260	    let registry = &registry;
261	
262	    let start = Instant::now();
263	    std::thread::scope(|s| {
264	        s.spawn(move || {
265	            if let Some((p, _)) = pin {
266	                pin_to_cpu(p);
267	            }
268	            for i in 0..count {
269	                let mut buf = pool
270	                    .alloc_with::<Msg>(policy::spin)
271	                    .expect("spin never gives up"); // OK: policy::spin never gives up
272	                buf.seq = i;
273	                let desc = registry
274	                    .into_desc(pool_id, buf)
275	                    .map_err(|(_, e)| e)
276	                    .expect("the guard is from the registered pool"); // OK: pool_id came from this registry's register
277	                send(desc);
278	            }
279	        });
280	        let consumer = s.spawn(move || {
281	            if let Some((_, c)) = pin {
282	                pin_to_cpu(c);
283	            }
284	            for i in 0..count {
285	                let desc = recv();
286	                // SAFETY: the descriptor was minted by the
287	                // producer's into_desc and read after the ring's
288	                // commit -> reserve handoff, and each is resolved
289	                // exactly once.
290	                let msg = unsafe { registry.resolve::<Msg>(desc) }
291	                    .expect("descriptors come from the producer's into_desc"); // OK: only the producer mints them, on this pool
292	                assert_eq!(msg.seq, i, "pool stream order broken");
293	                msg.free();
294	            }
295	        });
296	        consumer.join().expect("consumer panicked"); // OK: a panic in the consumer is the cell's failure
297	    });
298	    start.elapsed().as_secs_f64()
299	}
