301	/// The cordyceps cell: the queue links through the pool's
302	/// buffers. The producer allocs a buffer, lays the node over it,
303	/// and enqueues its pointer, and the consumer dequeues, asserts
304	/// the sequence, maps the pointer to the buffer's index, and
305	/// frees through the registry. Returns the seconds and the
306	/// `Inconsistent` results the consumer retried.
307	fn cell_cordyceps(pin: Option<(usize, usize)>, pool_size: u32, count: u64) -> (f64, u64) {
308	    let mut pool_region = LineBuf::new(pool_region_size(pool_size));
309	    let mut pool = Pool::init(
310	        pool_region.as_mut_bytes(),
311	        CACHE_LINE_SIZE as u32,
312	        pool_size,
313	    )
314	    .expect("region sized for the pool and line-aligned"); // OK: the region is the pool's own size and LineBuf is line-aligned
315	    let mut registry = PoolRegistry::<1>::new();
316	    let pool_id = registry
317	        .register(pool.resolver())
318	        .expect("an empty registry has room"); // OK: capacity 1, nothing registered yet
319	    let registry = &registry;
320	
321	    // Buffer 0's address, so the consumer can turn a node
322	    // pointer back into an index: alloc one, read its address
323	    // and index, and hand it back.
324	    let base = {
325	        let probe = pool
326	            .alloc::<RawBuf>()
327	            .expect("a fresh pool has a free buffer"); // OK: nothing allocated yet and pool_size is at least 1
328	        let addr = ptr::from_ref::<RawBuf>(&probe) as usize;
329	        let desc = registry
330	            .into_desc(pool_id, probe)
331	            .map_err(|(_, e)| e)
332	            .expect("the guard is from the registered pool"); // OK: pool_id came from this registry's register
333	        // SAFETY: the descriptor was minted just above and is
334	        // resolved once, on this thread.
335	        unsafe { registry.resolve::<RawBuf>(desc) }
336	            .expect("the descriptor was minted just above") // OK: same pool, index in range
337	            .free();
338	        addr - desc.buf_idx as usize * CACHE_LINE_SIZE
339	    };
340	
341	    // The stub the queue owns, leaked so it is static: a
342	    // handful of bytes per cell, and the queue's drop then
343	    // touches nothing the pool owns.
344	    let stub: &'static Node = Box::leak(Box::new(Node {
345	        pool_link: 0,
346	        links: Links::new_stub(),
347	        seq: 0,
348	    }));
349	    // SAFETY: the stub's links are `new_stub`, it is leaked so
350	    // it lives as long as the program, and nothing else touches
351	    // it.
352	    let queue = unsafe { MpscQueue::<Node>::new_with_static_stub(stub) };
353	    let queue = &queue;
354	
355	    let start = Instant::now();
356	    let inconsistent = std::thread::scope(|s| {
357	        s.spawn(move || {
358	            if let Some((p, _)) = pin {
359	                pin_to_cpu(p);
360	            }
361	            for i in 0..count {
362	                let mut buf = pool
363	                    .alloc_with::<RawBuf>(policy::spin)
364	                    .expect("spin never gives up"); // OK: policy::spin never gives up
365	                let node = ptr::from_mut::<RawBuf>(&mut buf).cast::<Node>();
366	                // Keep the buffer allocated without a guard: the
367	                // consumer frees it by index.
368	                registry
369	                    .into_desc(pool_id, buf)
370	                    .map_err(|(_, e)| e)
371	                    .expect("the guard is from the registered pool"); // OK: pool_id came from this registry's register
372	                // SAFETY: the buffer is line-aligned and at least
373	                // a node long, allocated to this thread until the
374	                // consumer frees it, and no reference to it
375	                // exists.
376	                unsafe {
377	                    ptr::addr_of_mut!((*node).links).write(Links::new());
378	                    ptr::addr_of_mut!((*node).seq).write(i);
379	                    queue.enqueue(NodePtr(NonNull::new_unchecked(node)));
380	                }
381	            }
382	        });
383	        let consumer = s.spawn(move || {
384	            if let Some((_, c)) = pin {
385	                pin_to_cpu(c);
386	            }
387	            let guard = queue.consume();
388	            let mut inconsistent = 0u64;
389	            for i in 0..count {
390	                let node = loop {
391	                    match guard.try_dequeue() {
392	                        Ok(node) => break node,
393	                        Err(TryDequeueError::Inconsistent) => {
394	                            inconsistent += 1;
395	                            std::hint::spin_loop();
396	                        }
397	                        Err(TryDequeueError::Empty) => std::hint::spin_loop(),
398	                        Err(TryDequeueError::Busy) => {
399	                            unreachable!("the consumer guard is held")
400	                        }
401	                    }
402	                };
403	                let node = node.0.as_ptr();
404	                // SAFETY: the node is the consumer's from the
405	                // dequeue until the free below, and the producer
406	                // wrote `seq` before its enqueue's release.
407	                let seq = unsafe { ptr::addr_of!((*node).seq).read() };
408	                assert_eq!(seq, i, "pool stream order broken");
409	                let idx = ((node as usize - base) / CACHE_LINE_SIZE) as u32;
410	                let desc = Desc {
411	                    pool_id: pool_id.as_u32(),
412	                    buf_idx: idx,
413	                };
414	                // SAFETY: the index is the buffer the producer
415	                // allocated for this node, resolved once, after
416	                // the dequeue's acquire.
417	                unsafe { registry.resolve::<RawBuf>(desc) }
418	                    .expect("the index is a buffer of this pool") // OK: computed from a pool buffer's address
419	                    .free();
420	            }
421	            inconsistent
422	        });
423	        consumer.join().expect("consumer panicked") // OK: a panic in the consumer is the cell's failure
424	    });
425	    (start.elapsed().as_secs_f64(), inconsistent)
426	}
